const job = $('Read Job').first()?.json || {};
const allRows = $('Read Qualified Entities').all().map(function(i) { return i.json; });
const entityType = ($('Set Vars').item.json.entity_type || 'lead').toString();
const resultMode = $('Set Vars').item.json.result_mode || 'scored';
const requestedCount = $('Set Vars').item.json.requested_count;

// Boolean/string normalization for Sheets-represented acceptance proof fields.
function isTrue(v) {
  return v === true || v === 'true' || v === 'TRUE' || v === 'True' || v === 1 || v === '1';
}
// F-034 barrier: a lead requires persisted WF2 acceptance proof, not just score/status.
function acceptanceProofOk(e) {
  return (e.quality_decision === 'ACCEPT')
      && (e.region_status === 'MATCH')
      && isTrue(e.service_match)
      && (e.final_role === 'PRIVATE_DEMAND')
      && (e.freshness_status === 'CURRENT')
      && (e.actionability_status === 'ACTIONABLE');
}

// qualified-only:
//  - WF5 qualification (status qualified OR score >= 60) is required;
//  - for leads, persisted WF2 acceptance proof is ALSO required (F-034).
//  - company/tender semantics unchanged.
const qualified = allRows.filter(function(e) {
  const status = (e.status || '').toString().toLowerCase();
  const score = Number(e.total_score) || 0;
  const wf5Qualified = (status === 'qualified' || score >= 60);
  if (!wf5Qualified) return false;
  if (entityType === 'lead') return acceptanceProofOk(e);
  return true;
});

// dedupe
var seen = {}; var unique = [];
for (var i = 0; i < qualified.length; i++) {
  var e = qualified[i]; var key = '';
  if (e.lead_id) key = 'lead:' + e.lead_id;
  else if (e.company_id) key = 'company:' + e.company_id;
  else if (e.tender_id) key = 'tender:' + e.tender_id;
  else if (e.source_url) key = 'url:' + e.source_url;
  else key = 'fallback:' + (e.title || '') + '|' + (e.source_url || '');
  if (!seen[key]) { seen[key] = true; unique.push(e); }
}

// sort by total_score desc
unique.sort(function(a, b) { return (Number(b.total_score) || 0) - (Number(a.total_score) || 0); });

// requested_count cap (no padding)
var entities = unique;
if (requestedCount !== null && requestedCount !== undefined && requestedCount !== '') {
  const cap = Number(requestedCount);
  if (Number.isFinite(cap) && cap > 0) { entities = unique.slice(0, cap); }
}

const qualifiedCount = unique.length;
const isZeroResult = (resultMode === 'no_results') || (qualifiedCount === 0);
const avgScore = qualifiedCount ? Math.round(unique.reduce(function(s, e) { return s + (Number(e.total_score) || 0); }, 0) / qualifiedCount) : 0;
const stats = { total_found: qualifiedCount, qualified: qualifiedCount, avg_score: avgScore };

return [{ json: { job: job, entities: entities, stats: stats, entity_type: entityType, is_zero_result: isZeroResult, qualified_count: qualifiedCount, result_mode: resultMode } }];

