Сущности не найдены. Возможные причины: поисковые запросы не дали результатов, либо порог фильтрации слишком высок.

Найдено: 0
Квалифицировано: 0
Средний скор: 0
';
return [{ json: { markdown_report: md } }];

// FAIL-CLOSED: WF6 MD to HTML — unified extraction (direct markdown_report OR DeepSeek response)
const item = $input.first();
const jobId = $('Set Vars').item.json.job_id || 'unknown';
if (!item || !item.json) {
  throw new Error('WF6_LLM_RESPONSE_INVALID — job_id=' + jobId + ' — no input');
}
let md = null;
if (typeof item.json.markdown_report === 'string') {
  md = item.json.markdown_report;
} else {
  const rawResponse = item.json;
  if (!rawResponse.choices || !Array.isArray(rawResponse.choices) || rawResponse.choices.length === 0) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — choices absent');
  }
  const content = rawResponse.choices[0]?.message?.content;
  if (!content || typeof content !== 'string' || content.trim() === '') {
    throw new Error('WF6_LLM_RESPONSE_INVALID — content empty');
  }
  let parsed;
  try {
    const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(clean);
  } catch(e) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — JSON parse failed');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — not object');
  }
  md = parsed.markdown_report;
}
if (!md || typeof md !== 'string' || md.trim() === '') {
  throw new Error('WF6_LLM_RESPONSE_INVALID — markdown empty');
}
function mdToHtml(s){
  let h = s;
  h = h.replace(/^### (.*)$/gm,'<h3>$1</h3>');
  h = h.replace(/^## (.*)$/gm,'<h2>$1</h2>');
  h = h.replace(/^# (.*)$/gm,'<h1>$1</h1>');
  h = h.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
  h = h.replace(/\*(.+?)\*/g,'<em>$1</em>');
  h = h.replace(/`([^`]+)`/g,'<code>$1</code>');
  h = h.replace(/^\|(.+)\|$/gm,(m)=>{const cells=m.slice(1,-1).split('|').map(c=>c.trim());return '<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>';});
  h = h.replace(/(<tr>[\s\S]+?<\/tr>)/g,'<table>$1</table>');
  h = h.replace(/^- (.*)$/gm,'<li>$1</li>');
  h = h.replace(/(<li>[\s\S]+?<\/li>)/g,'<ul>$1</ul>');
  h = h.replace(/\n\n/g,'</p><p>');
  return '<p>' + h + '</p>';
}
const body = mdToHtml(md);
const date = new Date().toISOString().slice(0,10);
const html = '<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><title>OSINT ' + jobId + '</title><style>body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;max-width:800px;margin:40px auto;padding:20px;color:#222;line-height:1.6}h1{color:#1a365d;border-bottom:2px solid #1a365d;padding-bottom:8px}h2{color:#2c5282;margin-top:32px}h3{color:#2b6cb0}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{border:1px solid #ddd;padding:8px 12px;text-align:left}tr:nth-child(even){background:#f7fafc}code{background:#edf2f7;padding:2px 6px;border-radius:3px;font-family:SF Mono,Monaco,monospace}ul{padding-left:24px}.footer{margin-top:60px;padding-top:20px;border-top:1px solid #e2e8f0;color:#718096;font-size:12px}</style></head><body>' + body + '<div class="footer">OSINT Report Job: ' + jobId + ' Generated ' + date + '</div></body></html>';
return [{ json: { html: html, md: md, filename: 'OSINT_' + jobId + '_' + date + '.pdf', job_id: jobId } }];

// FAIL-CLOSED: WF6 Create HTML Binary
var html = $input.first()?.json?.html;
if (!html || typeof html !== 'string' || html.trim() === '') {
  throw new Error('WF6_HTML_MISSING — html field is absent, not a string, or empty');
}
const binaryData = await this.helpers.prepareBinaryData(html, 'index.html', 'text/html');
return [{ json: { ok: true }, binary: { 'index.html': binaryData } }];

const upload = $input.first();
const pdf = $('Gotenberg to PDF').first();
if (!pdf || !pdf.binary || !pdf.binary.data) {
  throw new Error('WF6_PDF_BINARY_MISSING_BEFORE_DELIVERY');
}
return [{
  json: upload.json || {},
  binary: {
    data: pdf.binary.data
  }
}];

